const BUY_FEE=.01, SELL_FEE=.01, START=5_000_000, TARGET=100_000_000, MAX_MONTH=30;
const money=(n:number)=>'$'+Math.round(n).toLocaleString('en-US');
const short=companyMoney;
export const initial=():State=>({month:1,cash:START,prices:Object.fromEntries(ASSETS.map(a=>[a.id,a.base])),positions:{},labs:0,headline:'Seed round closed. Your $5M is in the bank. Buy hardware low, sell high, and build a profitable lab.',history:['Month 1: Seed round funded.'],ended:false,ending:'',seed:Math.floor(Math.random()*1000000),threat:null,threatHistory:[],crisisResult:null});
function load(store:Pick<Storage,'getItem'|'setItem'>=localStorage):State{const saved=readLocal(store);return saved.kind==='ready'?saved.state as State:initial();}
function rng(n:number){const x=Math.sin(n*12.9898+78.233)*43758.5453;return x-Math.floor(x);}
function labCost(level:number){return 1_200_000+level*550_000;}
function monthlyRevenue(labs:number){return labs*420_000;}
function monthlyExpenses(labs:number){return labs*150_000;}
function monthlyProfit(labs:number){return monthlyRevenue(labs)-monthlyExpenses(labs);}
function portfolio(s:State){return ASSETS.reduce((sum,a)=>sum+(s.positions[a.id]?.qty||0)*s.prices[a.id],0);}
function valuation(s:State){const netAssets=s.cash+portfolio(s);const arr=monthlyRevenue(s.labs)*12;const margin=monthlyProfit(s.labs);return Math.max(0,20_000_000+netAssets+arr*3.25+(margin>0?margin*12*.3:0));}
function companyValuation(s:State){return valuation(s)+premium(s);}
const yearFor=(month:number)=>Math.floor((month-1)/12)+1;
const profitClass=(n:number)=>n>=0?'positive':'negative';
const signedMoney=(n:number)=>(n>=0?'+':'−')+money(Math.abs(n));
const acquirers=ACQUIRERS;
const threatKinds=['activist','takeover','vote'] as const;
function newThreat(month:number,seed:number):Threat{
 const kind=threatKinds[Math.floor(rng(seed+month*41)*3)];
 if(kind==='activist')return {month,kind,title:'ACTIVIST INVESTORS AT THE GATE',story:'A fund wants you to stop chasing GPUs and return cash to shareholders. They demand a response.'};
 if(kind==='takeover')return {month,kind,title:'HOSTILE TAKEOVER ATTEMPT',story:'A rival-backed consortium is accumulating shares and wants control of your AI lab.'};
 return {month,kind,title:'EMERGENCY SHAREHOLDER VOTE',story:'Investors want to replace the CEO after a brutal earnings call. That CEO is you.'};
}
function endingType(s:State):'fraud'|'bankrupt'|'ipo'|'acquisition'|'almost'|'hype'|'graveyard'{
 if(s.endingChoice==='fraud')return 'fraud';
 if(s.cash<0||s.endingChoice==='bankrupt')return 'bankrupt';
 const v=companyValuation(s);
 if(v>=150_000_000&&monthlyRevenue(s.labs)*12>=12_000_000&&monthlyProfit(s.labs)>0)return 'ipo';
 if(v>=TARGET)return 'acquisition';
 if(v>=50_000_000)return 'almost';
 if(v>=25_000_000)return 'hype';
 return 'graveyard';
}
const endings={
 fraud:{title:'THE SBF SUITE',kicker:'SPECIAL INVESTIGATION',body:'Your numbers were fictional. The regulators were not amused. Your next pitch meeting has bars on the windows.'},
 bankrupt:{title:'THE QUIET SHUTDOWN',kicker:'STARTUP OBITUARY',body:'You ran out of runway. The office furniture is on an auction site. Your investors have left the group chat.'},
 ipo:{title:'RING THE BELL',kicker:'IPO ELIGIBLE · FICTIONAL LISTING',body:'You have the valuation and revenue for our fictional IPO challenge. Wall Street has discovered you. Your inbox will never recover.'},
 acquisition:{title:'THE EXIT CLUB',kicker:'ACQUISITION OFFERS',body:'You crossed $100 million. Buyers are circling, and your investors are suddenly calling you a visionary.'},
 almost:{title:'ALMOST A UNICORN',kicker:'THE BUSINESS PRESS',body:'You built something real. Just not a $100M exit. The profile calls you a promising founder, which is investor-speak for “call us next year.”'},
 hype:{title:'THE AI HYPE MACHINE',kicker:'THE BUSINESS PRESS',body:'You raised millions, bought GPUs, and collected impressive acronyms. The investors would like to know where their exit went.'},
 graveyard:{title:'STARTUP GRAVEYARD',kicker:'THE FINAL POSTMORTEM',body:'Your startup went backward. The postmortem has more readers than your product had customers.'}
};


type SceneKind='profit'|'loss'|'flat'|'defense'|'defeat'|'ipo'|'acquisition'|'almost'|'hype'|'graveyard'|'bankrupt'|'fraud';
